import React, { useState } from 'react';
import { useTrackerData } from './hooks/useTrackerData';
import Sidebar, { MobileNav } from './components/Sidebar';
import Dashboard from './components/Dashboard';
import CalendarView from './components/CalendarView';
import Reports from './components/Reports';
import RewardsPanel from './components/RewardsPanel';
import NightReview from './components/NightReview';
import { Moon, Bell, Shield, AlertTriangle, Sun, Zap } from 'lucide-react';

const App: React.FC = () => {
  const {
    currentDay, calendarData, points, streak, badges,
    darkMode, notificationsEnabled,
    setDarkMode, setNotificationsEnabled,
    toggleTask, skipTask, completeDay, currentDayData,
  } = useTrackerData();

  const [view, setView] = useState('dashboard');
  const [showNightReview, setShowNightReview] = useState(false);

  const handleExport = () => {
    const blob = new Blob([JSON.stringify({ calendarData, points, streak, badges }, null, 2)], { type: 'application/json' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `180day-tracker-${new Date().toISOString().split('T')[0]}.json`;
    a.click();
  };

  const renderView = () => {
    switch (view) {
      case 'dashboard':
        return currentDayData ? (
          <Dashboard
            dayData={currentDayData}
            toggleTask={toggleTask}
            skipTask={skipTask}
            currentDay={currentDay}
          />
        ) : (
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '100%', color: '#475569', fontSize: 16 }}>
            Loading your challenge data...
          </div>
        );

      case 'calendar':
        return <CalendarView calendarData={calendarData} currentDay={currentDay} onSelectDay={() => {}} />;

      case 'reports':
        return <Reports calendarData={calendarData} onExport={handleExport} />;

      case 'rewards':
        return <RewardsPanel points={points} streak={streak} unlockedBadges={badges} />;

      case 'settings':
        return (
          <div style={{ padding: '32px 36px', maxWidth: 900, margin: '0 auto' }}>
            <div style={{ marginBottom: 36 }}>
              <div style={{ fontSize: 11, fontWeight: 700, color: '#475569', letterSpacing: '0.12em', textTransform: 'uppercase', marginBottom: 8 }}>Configuration</div>
              <h1 style={{ fontFamily: "'Space Grotesk',sans-serif", fontSize: 42, fontWeight: 700, color: '#F1F5F9', letterSpacing: '-0.02em' }}>Settings</h1>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 24 }}>
              {/* Appearance */}
              <div className="card-static" style={{ padding: '24px' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 22 }}>
                  <Shield size={18} color="#4F8EF7" />
                  <span style={{ fontSize: 14, fontWeight: 700, color: '#F1F5F9' }}>Appearance</span>
                </div>
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '16px 18px', borderRadius: 14, background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.06)' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                    {darkMode ? <Moon size={18} color="#4F8EF7" /> : <Sun size={18} color="#F59E0B" />}
                    <div>
                      <div style={{ fontSize: 13, fontWeight: 600, color: '#E2E8F0' }}>{darkMode ? 'Dark Mode' : 'Light Mode'}</div>
                      <div style={{ fontSize: 11, color: '#475569' }}>Toggle visual theme</div>
                    </div>
                  </div>
                  <button onClick={() => setDarkMode(!darkMode)} className={`toggle ${darkMode ? 'on' : 'off'}`}>
                    <div className="toggle-thumb" />
                  </button>
                </div>
              </div>

              {/* Notifications */}
              <div className="card-static" style={{ padding: '24px' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 22 }}>
                  <Bell size={18} color="#10B981" />
                  <span style={{ fontSize: 14, fontWeight: 700, color: '#F1F5F9' }}>Notifications</span>
                </div>
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '16px 18px', borderRadius: 14, background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.06)' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                    <Bell size={18} color={notificationsEnabled ? '#10B981' : '#475569'} />
                    <div>
                      <div style={{ fontSize: 13, fontWeight: 600, color: '#E2E8F0' }}>Browser Alerts</div>
                      <div style={{ fontSize: 11, color: '#475569' }}>6 AM · 9 PM · 11 PM</div>
                    </div>
                  </div>
                  <button
                    onClick={() => {
                      if (!notificationsEnabled) {
                        Notification.requestPermission().then(r => { if (r === 'granted') setNotificationsEnabled(true); });
                      } else {
                        setNotificationsEnabled(false);
                      }
                    }}
                    className={`toggle ${notificationsEnabled ? 'on' : 'off'}`}
                  >
                    <div className="toggle-thumb" />
                  </button>
                </div>
              </div>

              {/* Current stats */}
              <div className="card-static" style={{ padding: '24px' }}>
                <div style={{ fontSize: 14, fontWeight: 700, color: '#F1F5F9', marginBottom: 20 }}>Current State</div>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                  {[
                    { label: 'Current Day',   value: `Day ${currentDay} / 180`, color: '#4F8EF7' },
                    { label: 'Total Points',  value: points.toLocaleString(),    color: '#F59E0B' },
                    { label: 'Streak',        value: `${streak} days`,           color: '#10B981' },
                    { label: 'Badges Earned', value: `${badges.length} / 4`,     color: '#8B5CF6' },
                  ].map(s => (
                    <div key={s.label} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '10px 14px', borderRadius: 10, background: 'rgba(255,255,255,0.02)', border: '1px solid rgba(255,255,255,0.04)' }}>
                      <span style={{ fontSize: 12, color: '#64748B', fontWeight: 600 }}>{s.label}</span>
                      <span style={{ fontSize: 13, fontWeight: 700, color: s.color }}>{s.value}</span>
                    </div>
                  ))}
                </div>
              </div>

              {/* Danger zone */}
              <div className="card-static" style={{ padding: '24px', border: '1px solid rgba(248,113,113,0.15)', background: 'rgba(248,113,113,0.03)' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 22 }}>
                  <AlertTriangle size={18} color="#F87171" />
                  <span style={{ fontSize: 14, fontWeight: 700, color: '#F87171' }}>Danger Zone</span>
                </div>
                <p style={{ fontSize: 12, color: '#64748B', lineHeight: 1.6, marginBottom: 20 }}>
                  This will permanently erase all your progress — points, streaks, badges, and 180-day history. This action cannot be undone.
                </p>
                <button
                  onClick={() => {
                    if (window.confirm('⚠ Are you absolutely sure? All 180-day data will be deleted.')) {
                      localStorage.removeItem('180dayTracker');
                      window.location.reload();
                    }
                  }}
                  style={{ width: '100%', padding: '13px', borderRadius: 12, background: 'rgba(248,113,113,0.1)', border: '1px solid rgba(248,113,113,0.25)', color: '#F87171', fontSize: 13, fontWeight: 700, cursor: 'pointer', transition: 'all 0.2s', letterSpacing: '0.03em' }}
                  onMouseEnter={e => { (e.currentTarget as HTMLElement).style.background = 'rgba(248,113,113,0.18)'; }}
                  onMouseLeave={e => { (e.currentTarget as HTMLElement).style.background = 'rgba(248,113,113,0.1)'; }}
                >
                  Reset All Progress
                </button>
              </div>
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  // Determine if we're in "night hours" (after 9 PM)
  const isNight = new Date().getHours() >= 21;
  const dayNotDone = currentDayData && !currentDayData.completed;

  return (
    <div style={{ display: 'flex', minHeight: '100vh', background: '#070B14', color: '#F1F5F9' }}>
      {/* Sidebar (desktop) */}
      <Sidebar
        currentView={view}
        setCurrentView={setView}
        darkMode={darkMode}
        setDarkMode={setDarkMode}
        points={points}
        streak={streak}
      />

      {/* Main content */}
      <main style={{ flex: 1, overflowY: 'auto', height: '100vh', position: 'relative' }}>
        {/* Content */}
        <div style={{ paddingBottom: 120 }}>
          {renderView()}
        </div>

        {/* Floating Night Review Button */}
        {dayNotDone && (
          <div style={{ position: 'fixed', bottom: 32, right: 32, zIndex: 100 }}>
            {/* Pulsing ring */}
            {isNight && (
              <div style={{ position: 'absolute', inset: -8, borderRadius: 99, border: '2px solid rgba(79,142,247,0.4)', animation: 'pulse 2s infinite' }} />
            )}
            <button
              onClick={() => setShowNightReview(true)}
              className="btn-primary"
              style={{ padding: '16px 28px', borderRadius: 99, display: 'flex', alignItems: 'center', gap: 10, fontSize: 14, fontWeight: 700, letterSpacing: '0.02em', boxShadow: '0 8px 30px rgba(79,142,247,0.5)' }}
            >
              <Moon size={18} />
              {isNight ? 'Submit Night Review' : 'Early Review'}
              {isNight && <Zap size={14} fill="#fff" />}
            </button>
          </div>
        )}
      </main>

      {/* Mobile bottom nav */}
      <MobileNav currentView={view} setCurrentView={setView} />

      {/* Night Review Modal */}
      {showNightReview && currentDayData && (
        <NightReview
          dayData={currentDayData}
          onClose={() => setShowNightReview(false)}
          onComplete={(note, plan) => {
            completeDay(currentDay, note, plan);
            setShowNightReview(false);
          }}
        />
      )}
    </div>
  );
};

export default App;
